import java.util.*;

class Solution {
    public List<List<String>> solveNQueens(int n) {
        List<List<String>> answer = new ArrayList<>();
        Set<Integer> columns = new HashSet<>();
        Set<Integer> mainDiagonals = new HashSet<>();
        Set<Integer> antiDiagonals = new HashSet<>();
        char[][] board = new char[n][n];
        for (char[] row : board) {
            Arrays.fill(row, '.');
        }
        backtrack(0, board, columns, mainDiagonals, antiDiagonals, answer);
        return answer;
    }

    private void backtrack(int row, char[][] board, Set<Integer> columns,
                           Set<Integer> mainDiagonals, Set<Integer> antiDiagonals,
                           List<List<String>> answer) {
        int n = board.length;
        if (row == n) {
            answer.add(snapshot(board));
            return;
        }
        for (int col = 0; col < n; col++) {
            int main = row - col;
            int anti = row + col;
            if (columns.contains(col) || mainDiagonals.contains(main) || antiDiagonals.contains(anti)) {
                continue;
            }
            board[row][col] = 'Q';
            columns.add(col);
            mainDiagonals.add(main);
            antiDiagonals.add(anti);
            backtrack(row + 1, board, columns, mainDiagonals, antiDiagonals, answer);
            board[row][col] = '.';
            columns.remove(col);
            mainDiagonals.remove(main);
            antiDiagonals.remove(anti);
        }
    }

    private List<String> snapshot(char[][] board) {
        List<String> rows = new ArrayList<>();
        for (char[] row : board) {
            rows.add(new String(row));
        }
        return rows;
    }
}

import java.util.*;

class Solution {
    public List<List<String>> solveNQueens(int n) {
        List<List<String>> answer = new ArrayList<>();
        boolean[] columns = new boolean[n];
        boolean[] mainDiagonals = new boolean[2 * n - 1];
        boolean[] antiDiagonals = new boolean[2 * n - 1];
        char[][] board = new char[n][n];
        for (char[] row : board) {
            Arrays.fill(row, '.');
        }
        search(0, board, columns, mainDiagonals, antiDiagonals, answer);
        return answer;
    }

    private void search(int row, char[][] board, boolean[] columns,
                        boolean[] mainDiagonals, boolean[] antiDiagonals,
                        List<List<String>> answer) {
        int n = board.length;
        if (row == n) {
            answer.add(snapshot(board));
            return;
        }
        for (int col = 0; col < n; col++) {
            int main = row - col + n - 1;
            int anti = row + col;
            if (columns[col] || mainDiagonals[main] || antiDiagonals[anti]) {
                continue;
            }
            board[row][col] = 'Q';
            columns[col] = true;
            mainDiagonals[main] = true;
            antiDiagonals[anti] = true;
            search(row + 1, board, columns, mainDiagonals, antiDiagonals, answer);
            board[row][col] = '.';
            columns[col] = false;
            mainDiagonals[main] = false;
            antiDiagonals[anti] = false;
        }
    }

    private List<String> snapshot(char[][] board) {
        List<String> rows = new ArrayList<>();
        for (char[] row : board) {
            rows.add(new String(row));
        }
        return rows;
    }
}

import java.util.*;

class Solution {
    public List<List<String>> solveNQueens(int n) {
        List<List<String>> answer = new ArrayList<>();
        char[][] board = new char[n][n];
        for (char[] row : board) {
            Arrays.fill(row, '.');
        }
        backtrack(0, n, 0, 0, 0, board, answer);
        return answer;
    }

    private void backtrack(int row, int n, int columns, int mainDiagonals, int antiDiagonals,
                           char[][] board, List<List<String>> answer) {
        if (row == n) {
            answer.add(snapshot(board));
            return;
        }
        int available = ((1 << n) - 1) & ~(columns | mainDiagonals | antiDiagonals);
        while (available != 0) {
            int bit = available & -available;
            int col = Integer.numberOfTrailingZeros(bit);
            board[row][col] = 'Q';
            backtrack(row + 1, n, columns | bit, (mainDiagonals | bit) << 1,
                    (antiDiagonals | bit) >> 1, board, answer);
            board[row][col] = '.';
            available -= bit;
        }
    }

    private List<String> snapshot(char[][] board) {
        List<String> rows = new ArrayList<>();
        for (char[] row : board) {
            rows.add(new String(row));
        }
        return rows;
    }
}

import java.util.*;

class Solution {
    public List<List<String>> solveNQueens(int n) {
        List<List<String>> answer = new ArrayList<>();
        int[] columns = new int[n];
        boolean[] used = new boolean[n];
        enumeratePermutations(0, columns, used, answer);
        return answer;
    }

    private void enumeratePermutations(int row, int[] columns, boolean[] used,
                                       List<List<String>> answer) {
        int n = columns.length;
        if (row == n) {
            if (hasNoDiagonalConflict(columns)) {
                answer.add(buildBoard(columns));
            }
            return;
        }
        for (int col = 0; col < n; col++) {
            if (used[col]) {
                continue;
            }
            columns[row] = col;
            used[col] = true;
            enumeratePermutations(row + 1, columns, used, answer);
            used[col] = false;
        }
    }

    private boolean hasNoDiagonalConflict(int[] columns) {
        Set<Integer> mainDiagonals = new HashSet<>();
        Set<Integer> antiDiagonals = new HashSet<>();
        for (int row = 0; row < columns.length; row++) {
            int col = columns[row];
            if (!mainDiagonals.add(row - col) || !antiDiagonals.add(row + col)) {
                return false;
            }
        }
        return true;
    }

    private List<String> buildBoard(int[] columns) {
        List<String> board = new ArrayList<>();
        for (int row = 0; row < columns.length; row++) {
            char[] line = new char[columns.length];
            Arrays.fill(line, '.');
            line[columns[row]] = 'Q';
            board.add(new String(line));
        }
        return board;
    }
}
